import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"755-批量根据excelA-B列内容移动文件夹到目标文件夹","日期":"2026-04-08T00:00:00.000Z","修改日期":"2026-04-08T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["搜索文件夹","文件夹对应移动","文件夹搜索并移动","文件夹移动"]},"headers":[],"relativePath":"md/文件及文件夹批处理/755-批量根据excelA-B列内容移动文件夹到目标文件夹.md","filePath":"md/文件及文件夹批处理/755-批量根据excelA-B列内容移动文件夹到目标文件夹.md"}'),n={name:"md/文件及文件夹批处理/755-批量根据excelA-B列内容移动文件夹到目标文件夹.md"};function l(p,t,s,i,c,_){return a(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="_755-批量根据excela-b列内容移动文件夹到目标文件夹" tabindex="-1">755-批量根据excelA-B列内容移动文件夹到目标文件夹 <a class="header-anchor" href="#_755-批量根据excela-b列内容移动文件夹到目标文件夹" aria-label="Permalink to &quot;755-批量根据excelA-B列内容移动文件夹到目标文件夹&quot;">​</a></h2><p>在源文件夹下搜索（支持子文件夹穿透）A列中的文件夹名，在目标文件夹下搜索（支持子文件夹穿透）B列的文件夹名</p><p>将A列中的文件夹移动到对应的B列中的文件夹内</p><p><strong>excell文件建议使用格式：xlsx</strong></p><p>**注意事项：**需要注意同名文件夹问题，避免覆盖</p><p><strong>程序和excell文件夹放在同一个文件夹内</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/spbVDYao3CQdk1O.png" alt="null" title="image-20241016104125288"></p><p><strong>excell文件格式如下所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/oRjqh869trsP3Lg.png" alt="null" title="image-20241016104219223"></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>假设Excel文件中A列有文件夹名E、F、D…等，B列有对应的目标文件夹名X、Y、Z等，</p><p>而文件夹A路径设置为”源文件夹总路径”，文件夹B路径设置为”目标文件夹总路径”。</p><p>运行程序后，程序会尝试将源文件夹下的E、F、D文件夹分别移动或复制到目标文件夹下的X、Y、Z文件夹内。</p><p>如果在源文件夹下的E文件无法移动或复制到目标文件夹下的X文件夹，则程序会在Excel文件中标记此问题。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/MVvtIozW6CJsOr2.png" alt="null" title="image-20241109183501115"></p><h3 id="📑-视频演示" tabindex="-1">📑 视频演示 <a class="header-anchor" href="#📑-视频演示" aria-label="Permalink to &quot;📑 视频演示&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1yXDBYUEoE/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yXDBYUEoE/</a></p><p>📑 本工具下载地址</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/406.html" target="_blank" rel="noreferrer">https://www.softbangong.com/406.html</a></p>',23)])])}const d=e(n,[["render",l]]);export{h as __pageData,d as default};
